package com.bank.network;

import java.util.logging.Logger;

public class SettlementNetworkCounter {

    private static final Logger log = Logger.getLogger(SettlementNetworkCounter.class.getName());
    private final int[] parent;
    private final int[] rank;
    private int components;

    public SettlementNetworkCounter(int n) {
        parent = new int[n];
        rank = new int[n];
        components = n;
        for (int i = 0; i < n; i++) parent[i] = i;
    }

    private int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    // returns true only on a real merge
    private boolean union(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return false;
        if (rank[ra] < rank[rb]) parent[ra] = rb;
        else if (rank[ra] > rank[rb]) parent[rb] = ra;
        else { parent[rb] = ra; rank[ra]++; }
        return true;
    }

    // count components after applying all links
    public int countNetworks(int[][] links) {
        for (int[] e : links) {
            if (union(e[0], e[1])) {
                components--;
                log.info(() -> "Link merged two networks; now=" + components);
            } else {
                log.fine(() -> "Link within existing network; count unchanged");
            }
        }
        log.info("Independent settlement networks: " + components);
        return components;
    }
}
