package com.bank.network;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class NetworkCountDemo {

    private static final Logger log = Logger.getLogger(NetworkCountDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Settlement Network Counter");
        // 5 branches (0..4), links below
        int[][] links = {{0, 1}, {1, 2}, {3, 4}};
        SettlementNetworkCounter counter = new SettlementNetworkCounter(5);
        int result = counter.countNetworks(links); // expect 2: {0,1,2} and {3,4}
        log.info("Result = " + result);
    }
}
